-- Veritabanı oluşturma
CREATE DATABASE okul;

-- Tablo oluşturma
CREATE TABLE ogrenciler (
    id INT PRIMARY KEY,
    ad VARCHAR(50),
    soyad VARCHAR(50)
);

-- Veri ekleme
INSERT INTO ogrenciler VALUES (1, 'Ali', 'Yılmaz');

-- Veri sorgulama
SELECT * FROM ogrenciler;

-- MySQL'e bağlanma
mysql -u root -p

-- Veritabanlarını listele
SHOW DATABASES;

-- MySQL sürümü
SELECT VERSION();

-- Veritabanı oluşturma
CREATE DATABASE kodlab;

-- Karakter seti ile
CREATE DATABASE kodlab
CHARACTER SET utf8mb4
COLLATE utf8mb4_unicode_ci;

-- Veritabanını kullanma
USE kodlab;

-- Silme
DROP DATABASE IF EXISTS kodlab_eski;

-- Mevcut DB
SELECT DATABASE();

-- Tüm kayıtlar
SELECT * FROM kullanicilar;

-- Belirli sütunlar
SELECT ad, soyad, email FROM kullanicilar;

-- WHERE ile filtrele
SELECT * FROM kullanicilar WHERE yas >= 18;
SELECT * FROM kullanicilar WHERE ad = 'Ali' AND yas > 20;

-- Sıralama
SELECT * FROM kullanicilar ORDER BY yas DESC;
SELECT * FROM kullanicilar ORDER BY soyad ASC, ad ASC;

-- DISTINCT
SELECT DISTINCT sehir FROM kullanicilar;

-- UPDATE
UPDATE kullanicilar
SET email = 'yeni@example.com', yas = 26
WHERE id = 1;

-- Tüm kayıtları güncelleme (dikkatli!)
UPDATE kullanicilar SET aktif = FALSE;

-- DELETE
DELETE FROM kullanicilar WHERE id = 5;

-- Tüm kayıtları silme
DELETE FROM kullanicilar;

-- TRUNCATE (tabloyu sıfırlar)
TRUNCATE TABLE kullanicilar;

-- NULL kayıtları bulma
SELECT * FROM kullanicilar WHERE email IS NULL;

-- NULL olmayan kayıtlar
SELECT * FROM kullanicilar WHERE email IS NOT NULL;

-- IFNULL kullanımı
SELECT ad, IFNULL(email, 'E-posta yok') AS email FROM kullanicilar;

-- COALESCE kullanımı
SELECT ad, COALESCE(telefon, email, 'İletişim bilgisi yok') AS iletisim
FROM kullanicilar;

-- LIMIT
SELECT * FROM kullanicilar LIMIT 5;

-- LIMIT + OFFSET (sayfalama)
SELECT * FROM kullanicilar LIMIT 10 OFFSET 0;
SELECT * FROM kullanicilar LIMIT 10 OFFSET 10;

-- Kısa OFFSET kullanımı
SELECT * FROM kullanicilar LIMIT 10, 10;

-- Sütun alias
SELECT ad AS isim, email AS 'e-posta' FROM kullanicilar;

-- Tablo alias
SELECT k.ad, s.tutar
FROM kullanicilar AS k
JOIN siparisler AS s ON k.id = s.kullanici_id;

-- %% wildcard
SELECT * FROM kullanicilar WHERE ad LIKE 'Ali%%';
SELECT * FROM kullanicilar WHERE ad LIKE '%%can';
SELECT * FROM kullanicilar WHERE ad LIKE '%%meh%%';

-- _ wildcard (tek karakter)
SELECT * FROM kullanicilar WHERE ad LIKE 'Ali_';
SELECT * FROM kullanicilar WHERE ad LIKE '____';

-- NOT LIKE
SELECT * FROM kullanicilar WHERE ad NOT LIKE '%%a%%';

-- IN kullanımı
SELECT * FROM kullanicilar WHERE sehir IN ('İstanbul', 'Ankara', 'İzmir');

-- NOT IN
SELECT * FROM kullanicilar WHERE sehir NOT IN ('İstanbul', 'Ankara');

-- BETWEEN (sayısal)
SELECT * FROM kullanicilar WHERE yas BETWEEN 18 AND 30;

-- BETWEEN (tarih)
SELECT * FROM siparisler WHERE siparis_tarihi BETWEEN '2024-01-01' AND '2024-12-31';

-- NOT BETWEEN
SELECT * FROM urunler WHERE fiyat NOT BETWEEN 100 AND 500;

-- COUNT
SELECT COUNT(*) AS toplam_kullanici FROM kullanicilar;
SELECT COUNT(DISTINCT sehir) AS farkli_sehir FROM kullanicilar;

-- SUM
SELECT SUM(bakiye) AS toplam_bakiye FROM hesaplar;

-- AVG
SELECT AVG(yas) AS ortalama_yas FROM kullanicilar;

-- MIN / MAX
SELECT MIN(yas) AS en_genc, MAX(yas) AS en_yasli FROM kullanicilar;

-- Hepsi bir arada
SELECT COUNT(*) AS toplam, SUM(tutar) AS toplam_tutar,
AVG(tutar) AS ortalama_tutar, MIN(tutar) AS en_dusuk,
MAX(tutar) AS en_yuksek FROM siparisler;

-- WHERE ile alt sorgu
SELECT * FROM siparisler
WHERE kullanici_id IN (
    SELECT id FROM kullanicilar WHERE aktif = TRUE
);

-- Scalar alt sorgu
SELECT ad, (SELECT COUNT(*) FROM siparisler WHERE kullanici_id = k.id) AS siparis_sayisi
FROM kullanicilar k;

-- FROM ile alt sorgu
SELECT sehir, ortalama_yas
FROM (SELECT sehir, AVG(yas) AS ortalama_yas FROM kullanicilar GROUP BY sehir) AS yas_ort
WHERE ortalama_yas > 25;

-- EXISTS
SELECT * FROM kullanicilar k
WHERE EXISTS (SELECT 1 FROM siparisler WHERE kullanici_id = k.id);

-- Index oluşturma
CREATE INDEX idx_soyad ON kullanicilar(soyad);

-- Benzersiz index
CREATE UNIQUE INDEX idx_email ON kullanicilar(email);

-- Çoklu sütun index
CREATE INDEX idx_ad_soyad ON kullanicilar(ad, soyad);

-- FULLTEXT index
CREATE FULLTEXT INDEX idx_icerik ON makaleler(baslik, icerik);

-- Index görüntüleme
SHOW INDEX FROM kullanicilar;

-- Index silme
DROP INDEX idx_soyad ON kullanicilar;

-- Sorgu planı
EXPLAIN SELECT * FROM kullanicilar WHERE email = 'ali@example.com';

-- 1NF öncesi (tekrarlayan gruplar)
CREATE TABLE siparis1nf (
    id INT PRIMARY KEY,
    musteri_adi VARCHAR(50),
    urun1 VARCHAR(50), urun2 VARCHAR(50), urun3 VARCHAR(50)
);

-- 1NF sonrası (atomik)
CREATE TABLE siparis (
    id INT PRIMARY KEY,
    musteri_adi VARCHAR(50)
);
CREATE TABLE siparis_kalem (
    id INT PRIMARY KEY,
    siparis_id INT,
    urun_adi VARCHAR(50),
    FOREIGN KEY (siparis_id) REFERENCES siparis(id)
);

-- 3NF
CREATE TABLE sehir (
    id INT PRIMARY KEY,
    sehir_adi VARCHAR(50),
    ulke VARCHAR(50)
);
